## TK-CRM-001 Contact Upsert v1.0.0
**Purpose:** Idempotent contact create/update — the ONLY writer to the contacts table.
**Input:** { company_id, request_id, payload: { phone?, email?, first_name?, last_name?, channels?, source?, tags?, custom_fields?, lead_score_delta?, lead_status? } }
**Output:** { ok, request_id, data: { contact }, error, meta }
**Config:** TK_SUPABASE_URL env + Supabase credential.
**Failure modes:** neither phone nor email → error missing_identifier. Upsert keys on (company_id, phone) or (company_id, email) → safe to retry.

parameters.jsCode:
const { company_id, request_id, payload } = $json;
const p = payload ?? {};

if (!company_id || !request_id) {
  return [{ json: { _error: { code: 'invalid_input', message: 'company_id and request_id are required', retryable: false }, request_id } }];
}
if (!p.phone && !p.email) {
  return [{ json: { _error: { code: 'missing_identifier', message: 'phone or email is required to upsert a contact', retryable: false }, request_id } }];
}

// Normalize identifiers so idempotency keys are stable.
const phone = p.phone ? String(p.phone).replace(/[^+\d]/g, '') : null;
const email = p.email ? String(p.email).trim().toLowerCase() : null;

return [{ json: {
  request_id,
  on_conflict: phone ? 'company_id,phone' : 'company_id,email',
  row: {
    company_id,
    ...(phone ? { phone } : {}),
    ...(email ? { email } : {}),
    ...(p.first_name ? { first_name: p.first_name } : {}),
    ...(p.last_name ? { last_name: p.last_name } : {}),
    ...(p.channels ? { channels: p.channels } : {}),
    ...(p.source ? { source: p.source } : {}),
    ...(p.tags ? { tags: p.tags } : {}),
    ...(p.custom_fields ? { custom_fields: p.custom_fields } : {}),
    ...(p.lead_status ? { lead_status: p.lead_status } : {}),
    updated_at: new Date().toISOString(),
  },
} }];

const contact = Array.isArray($json) ? $json[0] : $json;
const request_id = $('Validate & Normalize').first().json.request_id;
return [{ json: { ok: true, request_id, data: { contact }, error: null, meta: { workflow: 'TK-CRM-001', version: '1.0.0' } } }];
